import os
import google.cloud.documentai_v1 as documentai

def extract_receipt_fields(payload, config=None):
    config = config or {}
    project_id = os.environ.get("GCP_PROJECT_ID")
    location = os.environ.get("GCP_LOCATION", "us") # e.g., "us"
    processor_id = os.environ.get("GCP_RECEIPT_PROCESSOR_ID") # Create a "FORM_PARSER" or "RECEIPT_PARSER" processor in Document AI

    documentai_client = documentai.DocumentProcessorServiceClient()

    # The full resource name of the processor
    # e.g.: projects/project_id/locations/location/processors/processor_id
    resource_name = documentai_client.processor_path(project_id, location, processor_id)

    # Read the file into memory
    document_content = payload

    # Configure the process request
    request = documentai.ProcessRequest(
        name=resource_name,
        raw_document=documentai.RawDocument(
            content=document_content,
            mime_type="application/pdf"  # or "image/jpeg", "image/png", etc.
        )
    )

    result = documentai_client.process_document(request=request)
    document = result.document

    # Helper to extract text from a text anchor
    def _get_text_from_span(document, text_anchor):
        if not text_anchor.text_segments:
            return ""

        start_index = text_anchor.text_segments[0].start_index
        end_index = text_anchor.text_segments[0].end_index
        return document.text[start_index:end_index]

    extracted_data = {
        "merchant_name": None,
        "tax_amount": None,
        "total_amount": None,
        "items": []
    }

    # Extract entities
    for entity in document.entities:
        if entity.type == "merchant_name":
            extracted_data["merchant_name"] = _get_text_from_span(document, entity.text_anchor)
        elif entity.type == "total_tax":
            extracted_data["tax_amount"] = float(_get_text_from_span(document, entity.text_anchor))
        elif entity.type == "total_amount":
            extracted_data["total_amount"] = float(_get_text_from_span(document, entity.text_anchor))
        elif entity.type == "line_item":
            item = {}
            for prop in entity.properties:
                if prop.type == "description":
                    item["description"] = _get_text_from_span(document, prop.text_anchor)
                elif prop.type == "price":
                    item["price"] = float(_get_text_from_span(document, prop.text_anchor))
                elif prop.type == "quantity":
                    item["quantity"] = float(_get_text_from_span(document, prop.text_anchor))
            if item:
                extracted_data["items"].append(item)
    return extracted_data
